-- The analyst records what actually happened when executing a step.
DROP POLICY IF EXISTS "pol-financeanalyst-step_executions-insert" ON public.step_executions;
CREATE POLICY "pol-financeanalyst-step_executions-insert" ON public.step_executions FOR INSERT TO pko_finance_analyst WITH CHECK (true);
-- The analyst evidences requirement satisfaction as part of executing.
DROP POLICY IF EXISTS "pol-financeanalyst-requirement_satisfactions-insert" ON public.requirement_satisfactions;
CREATE POLICY "pol-financeanalyst-requirement_satisfactions-insert" ON public.requirement_satisfactions FOR INSERT TO pko_finance_analyst WITH CHECK (true);
-- The controller decides open change requests; a decided request is history and must not be rewritten.
DROP POLICY IF EXISTS "pol-controller-change_requests-update" ON public.change_requests;
CREATE POLICY "pol-controller-change_requests-update" ON public.change_requests FOR UPDATE TO pko_controller USING (public.calc_change_requests_is_open(change_request_id)) WITH CHECK (public.calc_change_requests_is_open(change_request_id));
-- The CFO decides open change requests escalated above the controller.
DROP POLICY IF EXISTS "pol-cfo-change_requests-update" ON public.change_requests;
CREATE POLICY "pol-cfo-change_requests-update" ON public.change_requests FOR UPDATE TO pko_cfo USING (public.calc_change_requests_is_open(change_request_id)) WITH CHECK (public.calc_change_requests_is_open(change_request_id));
-- The communications manager raises intents to send outbound messages.
DROP POLICY IF EXISTS "pol-communicationsmanager-send_intents-insert" ON public.send_intents;
CREATE POLICY "pol-communicationsmanager-send_intents-insert" ON public.send_intents FOR INSERT TO pko_communications_manager WITH CHECK (true);
-- A policy owner may revise the knowledge fragments its own role owns, and no others.
DROP POLICY IF EXISTS "pol-hrpolicyowner-knowledge_fragments-update" ON public.knowledge_fragments;
CREATE POLICY "pol-hrpolicyowner-knowledge_fragments-update" ON public.knowledge_fragments FOR UPDATE TO pko_hr_policy_owner USING (owner_role = app.jwt_role()) WITH CHECK (owner_role = app.jwt_role());

-- ---------- 5. Role schemas (the HORIZONTAL cut) ------------------
-- Each principal's schema is its ENTIRE visible world: it is the only
-- entry on their search_path, so a table absent from it cannot be
-- named, and a column absent from a view does not exist for them.

DROP SCHEMA IF EXISTS pko_finance_analyst CASCADE;
CREATE SCHEMA pko_finance_analyst;
GRANT USAGE ON SCHEMA pko_finance_analyst TO pko_finance_analyst;
REVOKE CREATE ON SCHEMA pko_finance_analyst FROM pko_finance_analyst;
ALTER ROLE pko_finance_analyst SET search_path = pko_finance_analyst;

DROP SCHEMA IF EXISTS pko_controller CASCADE;
CREATE SCHEMA pko_controller;
GRANT USAGE ON SCHEMA pko_controller TO pko_controller;
REVOKE CREATE ON SCHEMA pko_controller FROM pko_controller;
ALTER ROLE pko_controller SET search_path = pko_controller;

